{
  /* Chanukah slide: candle glows + twinkling stars placed on the real image (object-fit: cover) */
  const img=document.getElementById('chanImg'), fx=document.getElementById('chanFx'), scene=document.getElementById('chanScene');
  const IW=1900, IH=892;
  const flames=[[11.9,15.6],[15.0,15.3],[18.1,15.3],[21.2,15.3],[24.0,9.2],[27.6,15.0],[30.6,15.0],[33.6,14.6],[37.0,14.6]];
  const stars=[[58,26],[44,33],[62,41],[68,32],[52,46],[74,24],[81,38],[88,20],[47,21],[93,44],[71,52],[56,58],[84,57],[40,48]];
  flames.forEach((f,k)=>{const d=document.createElement('span');d.className='chan-glow';d.dataset.x=f[0];d.dataset.y=f[1];d.style.animationDelay=(-k*0.37)+'s';d.style.animationDuration=(1.6+(k%3)*0.45)+'s';fx.appendChild(d);});
  stars.forEach((st,k)=>{const d=document.createElement('span');d.className='chan-star';d.dataset.x=st[0];d.dataset.y=st[1];d.style.animationDelay=(k*0.53%3.2)+'s';d.style.animationDuration=(2.4+(k%4)*0.6)+'s';fx.appendChild(d);});
  function place(){
    const W=scene.clientWidth,H=scene.clientHeight; if(!W||!H)return;
    const sc=Math.max(W/IW,H/IH), rw=IW*sc, rh=IH*sc;
    const px=parseFloat(getComputedStyle(img).objectPosition.split(' ')[0])/100||0.3;
    const ox=(W-rw)*px, oy=(H-rh)*0.5;
    fx.querySelectorAll('span').forEach(el=>{el.style.left=(ox+rw*el.dataset.x/100)+'px';el.style.top=(oy+rh*el.dataset.y/100)+'px';el.style.setProperty('--s',sc);});
  }
  new ResizeObserver(place).observe(scene); img.complete?place():img.addEventListener('load',place);
}

ppScript:
{
  const price=document.getElementById('ppPrice'), note=document.getElementById('ppPriceNote');
  document.querySelectorAll('.pp-opt input').forEach(r=>r.addEventListener('change',()=>{price.textContent='₪'+r.value;note.textContent=r.dataset.note;}));
  document.querySelectorAll('[data-pq]').forEach(b=>b.addEventListener('click',()=>{const i=document.getElementById('ppQty');i.value=Math.max(1,(+i.value||1)+(+b.dataset.pq));}));
  const add=document.getElementById('ppAdd'); add.addEventListener('click',()=>{add.querySelector('span').textContent='נוסף לסל ✓';setTimeout(()=>add.querySelector('span').textContent='הוספה לסל',2200);});
  document.getElementById('ppWish').addEventListener('click',e=>e.currentTarget.classList.toggle('on'));
  document.querySelectorAll('.shop-icon.wish').forEach(b=>b.addEventListener('click',()=>b.classList.toggle('on')));
  const tabs=document.querySelectorAll('.pp-tablist button');
  tabs.forEach(t=>t.addEventListener('click',()=>{tabs.forEach(x=>{x.classList.toggle('active',x===t);x.setAttribute('aria-selected',x===t)});document.querySelectorAll('.pp-pane').forEach(p=>p.classList.toggle('active',p.id===t.dataset.t));}));
  const main=document.getElementById('ppMain'), img=document.getElementById('ppImg');
  main.addEventListener('mousemove',e=>{const r=main.getBoundingClientRect();img.style.transformOrigin=((e.clientX-r.left)/r.width*100)+'% '+((e.clientY-r.top)/r.height*100)+'%';img.style.transform='scale(1.6)';});
  main.addEventListener('mouseleave',()=>{img.style.transform='';});
}
